"""Build the editorial Tamil Nadu guide and district articles from reviewed briefs."""
from pathlib import Path
import json, re, html
ROOT=Path(__file__).resolve().parent.parent
BASE='https://saigraphicdesings.com'
DATA=json.loads((ROOT/'scripts/content/district-design-briefs.json').read_text())
assert len(DATA)==38 and len({row[0] for row in DATA})==38
esc=lambda x:html.escape(x,quote=True)
slug=lambda name:re.sub(r'[^a-z0-9]+','-',name.lower()).strip('-')
state='best-graphic-designer-tamilnadu'
hub='tamil-nadu-district-design-blogs'
styles='''<style>.article-meta{color:#52665f;font-size:.95rem}.district-badge{display:inline-block;background:#e8f5ee;color:#075c43;padding:.35rem .65rem;border-radius:6px;font-weight:700}.guide-nav{margin:22px 0;display:flex;gap:14px;flex-wrap:wrap}.guide-grid h2,.guide-grid h3{margin-top:0}.guide-grid a{display:block}.brief-example{padding:20px;border:1px solid #dce7e2;border-radius:12px;margin:20px 0;background:#fbfdfc}details{border:1px solid #dce7e2;border-radius:10px;padding:16px;margin:14px 0}summary{cursor:pointer;font-weight:700}main p,main li,td{overflow-wrap:anywhere}header nav{align-items:center}caption{text-align:left;font-weight:700;margin:12px 0}h3{margin-top:24px}footer .footer-inner{max-width:1000px;margin:auto}</style>'''
def page(path,title,description,body,crumbs,article=True):
 url=BASE+'/'+path
 entity={'@type':'BlogPosting' if article else 'CollectionPage','@id':url+'#article' if article else url+'#collection','headline':title,'name':title,'description':description,'url':url,'mainEntityOfPage':url,'inLanguage':'en-IN','author':{'@type':'Organization','name':'Sai Graphic Designs','url':BASE+'/about'},'publisher':{'@type':'Organization','name':'Sai Graphic Designs','url':BASE+'/'},'about':{'@type':'Thing','name':'Choosing graphic design services in Tamil Nadu'}}
 breadcrumbs={'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':name,'item':BASE+target} for i,(name,target) in enumerate([('Home','/'),('Blog','/blog')]+crumbs)]}
 schema=json.dumps({'@context':'https://schema.org','@graph':[entity,breadcrumbs]},ensure_ascii=False).replace('<','\\u003c')
 return f'''<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Sai Graphic Designs</title><meta name="description" content="{esc(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}"><link rel="icon" href="Images/favicon.png"><link rel="stylesheet" href="learning.css">{styles}<meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{url}"><meta property="og:locale" content="en_IN"><meta property="og:image" content="{BASE}/Images/logo.png"><meta name="twitter:card" content="summary"><script type="application/ld+json">{schema}</script><script src="/analytics.js" defer></script></head><body><header><a class="brand" href="index.html">Sai Graphic Designs</a><nav aria-label="Main navigation"><a href="customizer.html">Services</a><a href="blog.html">Blog</a><a href="{hub}.html">District guides</a><a href="contact.html">Contact</a></nav></header><main>{body}</main><footer><div class="footer-inner"><strong>Sai Graphic Designs</strong> · Main studio: Madurai, Tamil Nadu, India<br>110, Meenakshi Nagar 2nd Street, HMS Colony, Ponmeni, Madurai 625016<br><a href="tel:+916381128781">+91 63811 28781</a> · <a href="mailto:saigraphicdesings@gmail.com">saigraphicdesings@gmail.com</a><br><a href="about.html">About</a> · <a href="blog.html">Blog</a> · <a href="{hub}.html">Tamil Nadu district guides</a> · <a href="contact.html">Request a quote</a></div></footer></body></html>'''
def article_name(row):return 'best-graphic-designer-'+slug(row[0])
def card(row):
 name,ta,a,*_=row
 return f'<article class="guide-card"><h3><a href="{article_name(row)}.html">{esc(name)} <span lang="ta">· {ta}</span></a></h3><p>{esc(a)} and a second project example, plus a brief checklist and district-specific questions.</p></article>'
files=[]
for i,row in enumerate(DATA):
 name,ta,project,scenario,checkpoint,project2,scenario2,question,answer=row
 path=article_name(row);title=f'Best Graphic Designer in {name}: A Business Guide'
 description=f'Choosing a graphic designer in {name}? Compare portfolios and quotes with practical briefs for {project[0].lower()+project[1:]} and more.'
 office='Our physical studio is in Ponmeni, Madurai. Contact us to arrange a visit or share your brief online.' if name=='Madurai' else f'Businesses in {name} can work with Sai Graphic Designs online. Our physical studio is in Madurai; we do not list a separate {name} branch.'
 related=DATA[(i+1)%len(DATA)]
 # Illustrative briefs do not imply client work or district industry claims.
 body=f'''<article><p><a href="blog.html">Blog</a> / <a href="{hub}.html">Tamil Nadu district guides</a> / {esc(name)}</p><span class="district-badge">{esc(name)} · <span lang="ta">{ta}</span></span><h1>{esc(title)}</h1><p class="article-meta">By Sai Graphic Designs · Business planning guide</p><p class="answer">The best graphic designer in {esc(name)} for your project is the one whose relevant work, communication and final-file delivery match your brief. Review portfolio examples, clarify the scope and compare quotations before deciding. {office}</p><p>This guide uses two illustrative project briefs to show what to look for. They are planning examples, not claims about completed clients or a ranking of district designers.</p>
<h2>Project example: {esc(project)}</h2><p>{esc(scenario)}</p><div class="brief-example"><h3>What to check in the proof</h3><p>{esc(checkpoint)}</p></div>
<h2>A different brief: {esc(project2)}</h2><p>{esc(scenario2)}</p>
<h2>Build a useful brief for your {esc(name)} project</h2><p>Start with the audience and the action you want the design to support. Then list each deliverable: size, number of pages or variants, language versions and intended use. Supply approved text and the clearest available logo or product images.</p><ul><li><strong>Language:</strong> Tell us whether you need Tamil, English or separate versions. Have a fluent reviewer approve spelling, names and technical wording.</li><li><strong>Production:</strong> Send your printer’s template or dieline when relevant. Ask for a realistic size proof before approving artwork.</li><li><strong>Budget:</strong> Compare the same scope, revision rounds and file formats across quotes. Additional items and a new design direction should be agreed separately.</li><li><strong>Handover:</strong> Identify the editing software your team uses and the export formats your supplier needs. Editable-file delivery depends on the agreed package.</li></ul>
<h2>Questions from businesses planning work in {esc(name)}</h2><details open><summary>{esc(question)}</summary><p>{esc(answer)}</p></details><details><summary>Can I work with Sai Graphic Designs from {esc(name)}?</summary><p>{office} Send your brief, deadline and required formats through our contact page. We confirm the scope, revisions, schedule and payment steps before work begins.</p></details><details><summary>Does the design quote include printing and delivery?</summary><p>Design files and physical production are separate unless the quotation states otherwise. Confirm the product, quantity and delivery location before arranging printing or dispatch.</p></details>
<h2>Choose the next step for your project</h2><p>Review our <a href="customizer.html">design service galleries</a>, <a href="business-card-design-madurai.html">business card design</a>, <a href="brochure-design-madurai.html">brochure design</a> and <a href="packaging-design-madurai.html">packaging artwork</a>. Share which example fits your requirement and explain what should be different for your brand.</p><p><a class="action" href="contact.html">Request a quote for your {esc(name)} project →</a></p><nav class="guide-nav" aria-label="Related guides"><a href="{state}.html">Tamil Nadu designer selection guide</a><a href="{hub}.html">All 38 district guides</a><a href="{article_name(related)}.html">{esc(related[0])} project guide</a></nav></article>'''
 (ROOT/(path+'.html')).write_text(page(path,title,description,body,[('District guides','/'+hub),(name,'/'+path)]));files.append(path)
state_title='Best Graphic Designer in Tamil Nadu: How to Choose'
state_body=f'''<article><p><a href="blog.html">Blog</a> / Tamil Nadu</p><span class="district-badge">TAMIL NADU · STATEWIDE DESIGN GUIDE</span><h1>{state_title}</h1><p class="article-meta">By Sai Graphic Designs · Includes separate guides for all 38 districts</p><p class="answer">To choose the best graphic designer in Tamil Nadu for your business, compare relevant portfolio work, clarity of communication, production knowledge and the final files included in the quote. Sai Graphic Designs offers logo design, brand identity, business cards, brochures, packaging and social media artwork from its studio in Madurai, with online project handling across Tamil Nadu.</p><p>There is no single design style that suits every business. A retail poster, an equipment catalog and a product label need different decisions. Use this guide to define your requirements, then explore the separate district articles for practical project examples. If you searched for “best graphic designer in Tamilnadu,” start with the evidence below rather than relying on a superlative alone.</p>
<nav class="guide-nav" aria-label="Article contents"><a href="#compare">Compare designers</a><a href="#services">Choose services</a><a href="#workflow">Plan the project</a><a href="#districts">District blogs</a><a href="#faq">FAQs</a></nav>
<h2 id="compare">What makes a designer the right fit?</h2><p>Look at work that resembles your requirement. A collection of social posts may show visual style, but a packaging project also needs a discussion about dielines and production files. Ask to see relevant examples and clarify whether each is client work, a concept or a mockup.</p><div class="table-wrap"><table><caption>A practical designer comparison checklist</caption><thead><tr><th scope="col">Criterion</th><th scope="col">Evidence to request</th></tr></thead><tbody><tr><th scope="row">Relevant work</th><td>Examples of the same design type, with an explanation of the designer’s role.</td></tr><tr><th scope="row">Readable layout</th><td>A proof at the real size or intended viewing distance.</td></tr><tr><th scope="row">Production preparation</th><td>A plan for using your printer’s approved size, bleed, dieline and export requirements.</td></tr><tr><th scope="row">Language handling</th><td>Space for reviewed Tamil and English copy, with a clear approval process.</td></tr><tr><th scope="row">Quotation</th><td>Deliverables, variations, revisions, schedule and payment steps in writing.</td></tr><tr><th scope="row">Final handover</th><td>Agreed editable and export formats, plus any font or asset requirements.</td></tr></tbody></table></div>
<h2 id="services">Choose services around the work your business needs</h2><p>A logo project can include a new identity or <a href="logo-recreation-madurai.html">vector recreation of an existing mark</a>. A branding package may coordinate a logo, business card, letterhead and envelope. A brochure or catalog needs approved text and a defined page count. Packaging requires actual production dimensions and approved product copy.</p><p>Sai Graphic Designs provides <a href="logo-design-madurai.html">logo design</a>, <a href="business-card-design-madurai.html">business card design</a>, <a href="brochure-design-madurai.html">brochure design</a>, <a href="packaging-design-madurai.html">packaging artwork</a> and digital campaign graphics. See our <a href="customizer.html">service galleries</a> and explain the intended use when requesting a quote.</p><h3>One design system, several practical outputs</h3><p>For example, a business launch might need a logo, shop sign, business card and social announcement. Start by agreeing on brand elements, then check each output in its own context. A sign must be readable from a distance; a business card must keep small contact details clear. Sharing colors and typography does not mean shrinking one artwork into every format.</p>
<h2 id="workflow">Plan a clear Tamil Nadu design project</h2><ol><li><strong>Prepare approved content.</strong> Supply your business name, logo references, final text, product images, dimensions and deadline.</li><li><strong>Confirm the scope.</strong> Agree on concepts, pages, language versions, variants and adaptations before work starts.</li><li><strong>Review one direction.</strong> Check the layout using realistic content rather than placeholder text.</li><li><strong>Consolidate feedback.</strong> Nominate one approver and send a clear list of changes for each round.</li><li><strong>Inspect the final files.</strong> Check spelling, details, page order, dimensions and supplier specifications in the exported artwork.</li></ol><p>Projects outside Madurai can be briefed and reviewed online. Printing, special finishes and dispatch require separate confirmation based on product, quantity and destination. A design quote should not be assumed to include every production service.</p>
<h2 id="districts">Separate graphic design blogs for every Tamil Nadu district</h2><p>Our <a href="{hub}.html">district blog directory</a> links to 38 individual articles. Each includes different illustrative briefs, a proofing checkpoint and practical questions. These are service-planning guides; the district names do not indicate a branch office.</p><div class="guide-grid">{''.join(card(row) for row in [DATA[2],DATA[3],DATA[13],DATA[30]])}</div><p><a class="action" href="{hub}.html">Explore all 38 district blogs →</a></p>
<h2 id="faq">Frequently asked questions</h2><details open><summary>Is Sai Graphic Designs the best graphic designer in Tamil Nadu?</summary><p>“Best” depends on the project, design preferences and working requirements. Review our examples, compare the scope and ask for a quote to decide whether our studio is the right fit. This article does not claim an independently verified statewide ranking.</p></details><details><summary>Where is the studio located?</summary><p>Our main studio is at 110, Meenakshi Nagar 2nd Street, HMS Colony, Ponmeni, Madurai 625016. Call +91 63811 28781 to arrange a suitable time. Projects from other districts are handled online.</p></details><details><summary>Can I request Tamil and English designs?</summary><p>Yes. Specify the language versions in your brief and supply approved text. Separate layouts may be needed when translation changes the amount of text or reading hierarchy.</p></details><details><summary>How much does graphic design cost?</summary><p>The quote depends on the design type, complexity, page count, variations, revisions and required files. Send your brief and budget range for an itemized scope and delivery schedule.</p></details><details><summary>Will I receive editable files?</summary><p>Confirm the editing software and formats before accepting the quote. CorelDRAW, Illustrator, Photoshop and export-file delivery depend on the project and agreed package.</p></details><p><a class="action" href="contact.html">Discuss your design project →</a></p></article>'''
(ROOT/(state+'.html')).write_text(page(state,state_title,'Compare graphic designers in Tamil Nadu by portfolio, pricing scope, Tamil-English design and final files. Explore Sai Graphic Designs and 38 district guides.',state_body,[('Tamil Nadu guide','/'+state)]));files.append(state)
hub_title='Graphic Design Blogs for All 38 Tamil Nadu Districts'
hub_body=f'''<p><a href="blog.html">Blog</a> / Tamil Nadu district guides</p><h1>{hub_title}</h1><p class="answer">Choose your district for a separate article about selecting a graphic designer, preparing a brief and checking the final artwork. Each guide includes different project examples and practical questions.</p><p>Sai Graphic Designs has its physical studio in Madurai. Projects from other districts can be handled online; these pages do not represent separate branch offices.</p><p>Start with <a href="{state}.html">Best Graphic Designer in Tamil Nadu: How to Choose</a> for the statewide comparison checklist.</p><div class="guide-grid">{''.join(card(row) for row in DATA)}</div><p>District names were checked against the <a href="https://tamilnadu.s3waas.gov.in/" rel="noopener noreferrer">Government of Tamil Nadu District Portal</a>. The project examples in our articles are illustrative briefs, not descriptions of district industries or completed client projects.</p>'''
(ROOT/(hub+'.html')).write_text(page(hub,hub_title,'Browse separate graphic design articles for all 38 Tamil Nadu districts, with project examples, design briefs, proofing tips and online service information.',hub_body,[('District guides','/'+hub)],False));files.append(hub)
p=ROOT/'blog.html';s=p.read_text();needle='<h2>More articles</h2>'
section=f'''<section aria-labelledby="tamil-nadu-blogs"><h2 id="tamil-nadu-blogs">Tamil Nadu &amp; District Design Blogs</h2><div class="blog-grid"><a class="blog-card" href="{state}.html"><small>Tamil Nadu · Designer selection</small><h3>Best Graphic Designer in Tamil Nadu: How to Choose</h3><p>Compare portfolios, project scope, language support and final files before choosing a design partner.</p><b>Read the statewide guide →</b></a><a class="blog-card" href="{hub}.html"><small>38 districts · Separate articles</small><h3>Find your Tamil Nadu district blog</h3><p>Distinct project examples, proofing checkpoints and FAQs for businesses in every district.</p><b>Browse all district blogs →</b></a></div></section>'''
assert needle in s
if 'aria-labelledby="tamil-nadu-blogs"' in s:
 s=re.sub(r'<section aria-labelledby="tamil-nadu-blogs">[\s\S]*?</section>',lambda m:section,s,count=1)
else:
 s=s.replace(needle,section+needle,1)
s=s.replace('Graphic Design Blog &amp; US Business Design Guides','Graphic Design Blog: Tamil Nadu, Districts &amp; US Guides');p.write_text(s)
p=ROOT/'sitemap.xml';s=p.read_text();extra=''.join(f'  <url><loc>{BASE}/{path}</loc><lastmod>2026-10-30</lastmod></url>\n' for path in files if f'{BASE}/{path}</loc>' not in s);p.write_text(s.replace('</urlset>',extra+'</urlset>'))
p=ROOT/'llms.txt';s=p.read_text();marker='## Tamil Nadu district blog articles';addition=f'''\n{marker}\n- Statewide selection guide: {BASE}/{state}\n- Directory of all 38 district articles: {BASE}/{hub}\n- District guides contain illustrative design briefs, proofing checkpoints and FAQs. They describe online service from the Madurai studio, not separate district offices or verified rankings.\n''';
if marker not in s:p.write_text(s+addition)
print(f'Generated {len(files)} pages: 38 district articles, statewide article and directory.')

# Keep regenerated district pages consistent with the shared blog presentation.
import subprocess, sys
subprocess.run([sys.executable, str(ROOT / "scripts/decorate-blog-pages.py")], check=True)
